INSERT INTO public.exam_config (class, is_open, total_questions, time_limit_minutes, passing_score, max_attempts, show_results_to_students)
INSERT INTO public.questions (class, subject_tag, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option)
VALUES
  (11, 'Keyboard Shortcuts', 'easy', 'To type a single capital letter or the "@" symbol above the number 2 without turning on Caps Lock, which key do you hold?', 'Shift', 'Alt', 'Ctrl', 'Tab', 'a'),
  (11, 'Keyboard Shortcuts', 'easy', 'Which shortcut opens a brand-new blank document or window in most apps?', 'Ctrl + D', 'Ctrl + B', 'Ctrl + N', 'Ctrl + M', 'c'),
  (11, 'Keyboard Shortcuts', 'easy', 'In a web browser like Chrome or Edge, what does pressing Ctrl + T do?', 'Closes the browser', 'Translates the page', 'Turns off Wi-Fi', 'Opens a new browser tab', 'd'),
  (11, 'Keyboard Shortcuts', 'easy', 'In a web browser, what does pressing Ctrl + W do?', 'Closes only the current tab', 'Opens Microsoft Word', 'Turns the screen white', 'Saves all bookmarks', 'a'),
  (11, 'Keyboard Shortcuts', 'easy', 'Which key on a Windows keyboard is used to capture a screenshot of your entire screen?', 'PrtSc (Print Screen)', 'Scroll Lock', 'Pause/Break', 'Page Down', 'a'),
  (11, 'Keyboard Shortcuts', 'easy', 'When a file or folder is selected on Windows, pressing which function key lets you RENAME it immediately?', 'F4', 'F8', 'F1', 'F2', 'd'),
  (11, 'Keyboard Shortcuts', 'easy', 'What does pressing Alt + F4 do on a Windows computer?', 'Turns on Bluetooth', 'Increases speaker volume', 'Closes the currently active app or window', 'Opens four new folders', 'c'),
  (11, 'Keyboard Shortcuts', 'medium', 'In a browser, pressing Ctrl and the "+" (plus) key together does what?', 'Zooms in to make text and images appear larger', 'Increases internet speed', 'Opens calculator', 'Adds a new user account', 'a'),
  (11, 'Keyboard Shortcuts', 'medium', 'After zooming in on a webpage, pressing Ctrl + 0 (zero) does what?', 'Mutes computer sound', 'Deletes the webpage', 'Resets the page zoom back to normal (100%)', 'Closes all tabs', 'c'),
  (11, 'Keyboard Shortcuts', 'medium', 'When filling out an online form (like Name, Roll No, Class), pressing the Tab key usually does what?', 'Closes the browser tab', 'Moves the cursor neatly to the next input box', 'Submits the form immediately', 'Erases what you typed', 'b'),
  (11, 'Keyboard Shortcuts', 'medium', 'If you step away from a computer for a minute, which Windows shortcut immediately LOCKS your screen?', 'Windows Key + L', 'Ctrl + L', 'Alt + L', 'Windows Key + O', 'a'),
  (11, 'Keyboard Shortcuts', 'medium', 'Which Windows shortcut minimizes all open windows at once so you can see the Desktop?', 'Windows Key + D', 'Windows Key + P', 'Ctrl + D', 'Alt + D', 'a'),
  (11, 'Keyboard Shortcuts', 'medium', 'You accidentally closed an important tab in Chrome/Edge! Which lifesaver shortcut reopens the last closed tab?', 'Ctrl + Alt + Z', 'Ctrl + Shift + T', 'Alt + Home', 'Shift + F5', 'b'),
  (11, 'Keyboard Shortcuts', 'medium', 'What happens when you delete a file using Shift + Delete instead of just pressing Delete?', 'It moves the file to Desktop', 'Nothing happens', 'It copies the file twice', 'It permanently deletes the file without sending it to the Recycle Bin', 'd'),
  (11, 'Keyboard Shortcuts', 'hard', 'Which Windows shortcut opens File Explorer ("This PC" / Folders) directly?', 'Alt + E', 'Ctrl + E', 'Windows Key + F', 'Windows Key + E', 'd'),
  (11, 'Keyboard Shortcuts', 'hard', 'While typing a sentence, holding Ctrl and pressing Backspace (Ctrl + Backspace) erases what?', 'The entire word to the left of the cursor at once', 'The entire document', 'Only punctuation marks', 'Only one single letter', 'a'),
  (11, 'Keyboard Shortcuts', 'hard', 'Which function key toggles Full-Screen mode ON or OFF in almost all web browsers?', 'F11', 'F3', 'F7', 'F1', 'a'),
  (11, 'Keyboard Shortcuts', 'hard', 'If a program freezes on Windows, which direct shortcut opens Task Manager immediately?', 'Windows Key + M', 'Ctrl + Alt + P', 'Ctrl + Shift + Esc', 'Shift + Tab', 'c'),
  (11, 'Computer Hardware', 'easy', 'What is the main job of the small spinning fan inside a laptop or desktop cabinet?', 'To boost Wi-Fi signal', 'To keep the processor and internal parts cool so the computer does not overheat', 'To blow dust onto the screen', 'To make music louder', 'b'),
  (11, 'Computer Hardware', 'easy', 'In everyday phones and computers, what is the simple difference between RAM and Storage (SSD/ROM)?', 'RAM holds active apps temporarily while working; Storage keeps your photos and files saved even when powered off', 'Both are names for the screen', 'RAM is only for printers', 'RAM stores photos forever; Storage deletes everything on restart', 'a'),
  (11, 'Computer Hardware', 'easy', 'If your computer opens 15 browser tabs and starts feeling sluggish when switching apps, having more of which part helps most?', 'A bigger mouse pad', 'RAM (working memory)', 'A louder speaker', 'A longer power cable', 'b'),
  (11, 'Computer Hardware', 'easy', 'Modern laptops use an SSD instead of an older spinning Hard Disk (HDD). What everyday benefit do you notice right away?', 'The screen becomes wider', 'The laptop boots up and opens apps much faster, with no moving disk parts', 'It prints paper automatically', 'You never need to charge the battery', 'b'),
  (11, 'Computer Hardware', 'easy', 'Which newer oval-shaped reversible charging/data port is found on almost all modern Android phones and newer laptops?', 'PS/2 round port', 'CD-ROM slot', 'USB Type-C (USB-C)', 'VGA port', 'c'),
  (11, 'Computer Hardware', 'easy', 'What do we call the main circuit board inside a computer that connects the processor, RAM, storage, and ports together?', 'Dashboard', 'Clipboard', 'Motherboard', 'Whiteboard', 'c'),
  (11, 'Computer Hardware', 'easy', 'If a wireless mouse stops moving the cursor on screen, what is the FIRST simple hardware thing you should check?', 'Check if its battery is low or its tiny power switch underneath is turned OFF', 'Buy a new monitor', 'Delete your files', 'Reinstall Windows immediately', 'a'),
  (11, 'Computer Hardware', 'medium', 'A pen-like tool used by digital artists and students to write or draw neatly on a tablet screen is called a:', 'Router antenna', 'Stylus', 'Laser printer', 'Thumb drive', 'b'),
  (11, 'Computer Hardware', 'medium', 'Which storage capacity is LARGER when comparing a pendrive or laptop storage?', '1 Kilobyte (1 KB)', '1 Gigabyte (1 GB)', '1 Terabyte (1 TB)', '1 Megabyte (1 MB)', 'c'),
  (11, 'Computer Hardware', 'medium', 'Roughly how many Gigabytes (GB) make 1 Terabyte (TB) on a hard drive?', 'About 10 GB', 'About 50 GB', 'About 2 GB', 'About 1,000 GB (1,024 GB)', 'd'),
  (11, 'Computer Hardware', 'medium', 'Before pulling out a USB pendrive while files are copying, why should you wait or click "Eject"?', 'Otherwise the monitor turns black forever', 'Pulling it out mid-write can corrupt or damage the files being saved', 'It uses up Wi-Fi data', 'The keyboard will lock', 'b'),
  (11, 'Computer Hardware', 'medium', 'Which computer component is specially helpful for smooth 3D video editing, animation, and modern games?', 'Floppy drive', 'GPU (Graphics Card / Graphics Processor)', 'RJ45 plug', 'Ink cartridge', 'b'),
  (11, 'Computer Hardware', 'medium', 'Why should you NEVER block the air vents on the bottom of a laptop by placing it deep into a thick blanket for hours?', 'It deletes browser bookmarks', 'It disconnects Bluetooth earbuds', 'It makes the screen brightness drop to zero', 'Blocked vents trap heat inside, causing overheating, slow performance, and battery wear', 'd'),
  (11, 'Computer Hardware', 'medium', 'A desktop monitor is turned ON, its power light is blinking, and it says "No Signal." What is the most likely practical cause?', 'The Recycle Bin is full', 'Caps Lock is pressed on the keyboard', 'Either the CPU cabinet is OFF or the HDMI/VGA display cable between the CPU and monitor is loose', 'The internet website is down', 'c'),
  (11, 'Computer Hardware', 'hard', 'What is the difference between putting a laptop to "Sleep" versus "Shut Down"?', 'Sleep erases all saved files', 'Shut Down uses more battery than playing games', 'Both are identical', 'Sleep keeps open work ready in low-power memory for instant wake-up; Shut Down closes everything completely', 'd'),
  (11, 'Computer Hardware', 'hard', 'What does screen resolution like "1920 × 1080 (Full HD)" describe on a monitor or phone?', 'How many files can fit on the desktop', 'The weight of the monitor in grams', 'The grid of tiny pixels (width × height) that makes up the sharpness of the display', 'How loud the speakers are', 'c'),
  (11, 'Computer Hardware', 'hard', 'An "All-in-One" desktop PC in a modern lab has no separate tower box on the desk. Where are its processor, RAM, and SSD located?', 'On the internet cloud only', 'Built neatly right behind the monitor screen itself', 'Inside the mouse', 'Inside the keyboard spacebar', 'b'),
  (11, 'Computer Hardware', 'hard', 'Why do ink-tank or laser printers usually cost much less per page for a school office than tiny cheap ink-cartridge printers?', 'They do not use paper', 'They only print on Sundays', 'They require no electricity', 'Refill ink bottles and toner print thousands of pages at a fraction of the cost per page', 'd'),
  (11, 'Application Software & OS', 'easy', 'Which long bar at the bottom of a Windows screen shows the Start button, pinned apps, and clock?', 'Taskbar', 'Formula bar', 'Bookmark bar', 'Scroll bar', 'a'),
  (11, 'Application Software & OS', 'easy', 'Why do many students turn on "Dark Mode" in apps when reading or working in the evening?', 'It uses a dark background that feels gentler on the eyes in low light', 'It makes Wi-Fi twice as fast', 'It doubles storage space', 'It prints pages in black paper', 'a'),
  (11, 'Application Software & OS', 'easy', 'If you want to jot down a quick plain-text note with zero heavy formatting, which lightweight built-in Windows app opens instantly?', 'Device Manager', 'Notepad', 'Media Player', 'Disk Defragmenter', 'b'),
  (11, 'Application Software & OS', 'easy', 'When saving an image with a transparent background (such as a school logo), which image format supports transparency cleanly?', '.txt', '.exe', '.png', '.mp3', 'c'),
  (11, 'Application Software & OS', 'easy', 'On Windows, files ending in ".exe" (or ".apk" on Android) are what kind of files?', 'Spreadsheet charts', 'Family vacation photos', 'Plain text essays', 'Application installer / executable program files (only run from trusted official sources!)', 'd'),
  (11, 'Application Software & OS', 'easy', 'Before editing an important project presentation, why is naming files clearly like "Science_Poster_v2_Final.pptx" better than "asdf123.pptx"?', 'Computers refuse to save short names', 'Long names increase RAM', 'It changes slide colors automatically', 'Clear file names let you and your teammates find the right version in seconds without confusion', 'd'),
  (11, 'Application Software & OS', 'easy', 'What does the "Spell Check" wavy red underline in Word or Google Docs indicate?', 'That the sentence will be deleted automatically', 'A word that may have a spelling typo so you can review and fix it', 'That the computer has a virus', 'That the font is bold', 'b'),
  (11, 'Application Software & OS', 'medium', 'If a single app stops responding ("Not Responding") on Windows, how can you close JUST that stuck app without unplugging the whole PC?', 'Tap the monitor glass', 'Pull the electric plug from the wall', 'Open Task Manager, select the frozen app, and click "End Task"', 'Format the hard drive', 'c'),
  (11, 'Application Software & OS', 'medium', 'What is "Open-Source Software" (such as Linux, VLC, Blender, or LibreOffice)?', 'Software whose source code is openly shared so anyone can use, study, and improve it legally', 'Software that works only for 1 hour', 'Broken trial software', 'Software that leaves your computer unlocked to strangers', 'a'),
  (11, 'Application Software & OS', 'medium', 'When you install a new PDF app and Windows asks which "Default App" should open .pdf files, what does that setting control?', 'Which program opens automatically whenever you double-click any .pdf file', 'Which user owns the computer', 'How fast the internet runs', 'Whether printing is allowed', 'a'),
  (11, 'Application Software & OS', 'medium', 'In Google Docs or Microsoft 365 Online, what is a huge everyday advantage of "Auto-Save" to the cloud?', 'It writes your homework by itself', 'Your latest edits are saved continuously, so a sudden power cut does not wipe out an hour of typing', 'It prints every page automatically', 'It works without turning on the screen', 'b'),
  (11, 'Application Software & OS', 'medium', 'What is the purpose of Windows Security / Antivirus software on a PC?', 'To edit birthday videos', 'To design school logos', 'To detect and block harmful malware or infected downloads before they damage your files', 'To clean physical dust off the keyboard', 'c'),
  (11, 'Application Software & OS', 'medium', 'Why do phones and laptops let you turn off unnecessary "Startup Apps" in Settings?', 'It turns off the screen color', 'It disables the keyboard', 'It uninstalls those apps permanently', 'Fewer heavy apps launching automatically at boot makes the computer start up faster and saves memory', 'd'),
  (11, 'Application Software & OS', 'medium', 'When you download a `.zip` archive of club photos, why should you "Extract All" before editing the photos inside?', 'Otherwise the photos turn black and white', 'Zip files vanish after 5 minutes', 'Extracting doubles photo resolution', 'Extracting unpacks the compressed files into a normal folder so apps can open and save changes properly', 'd'),
  (11, 'Application Software & OS', 'hard', 'What does "Version History" in Google Docs, Slides, or Sheets let a student team do?', 'Check the laptop manufacturing year', 'See earlier saved versions of a document and restore work if someone accidentally erased a section', 'See every website visited on the computer', 'Speed up the CPU', 'b'),
  (11, 'Application Software & OS', 'hard', 'If you copy a song file onto your Desktop as a "Shortcut" (tiny arrow on the icon) and then copy ONLY that shortcut to a pendrive, what happens at school?', 'It converts the song into a video', 'It plays twice as loud', 'It will NOT play, because a shortcut is only a pointer link — not the actual `.mp3` song file itself!', 'It copies your entire computer', 'c'),
  (11, 'Application Software & OS', 'hard', 'What is a `.csv` (Comma-Separated Values) file commonly used for between apps like Excel, Google Sheets, and portals?', 'Importing or exporting simple clean rows and columns of table data (like student lists or questions)', 'Recording voice notes', 'Editing photo brightness', 'Playing 3D animations', 'a'),
  (11, 'Application Software & OS', 'hard', 'On a phone or computer, what is the difference between "Clearing App Cache" and "Clearing App Data / Storage"?', 'Clearing Cache removes temporary files safely; Clearing Data resets the app like a fresh install and logs you out', 'Clearing Cache deletes all your contacts', 'Both uninstall the operating system', 'Neither frees any space', 'a'),
  (11, 'Web Browsing & Internet', 'easy', 'Why do websites sometimes ask you to tick "I am not a robot" or pick traffic lights (CAPTCHA)?', 'To stop automated spam bots from creating fake accounts or flooding forms', 'To test your eyesight for driving', 'To slow down your internet', 'To update your browser', 'a'),
  (11, 'Web Browsing & Internet', 'easy', 'In Chrome or Edge, which shortcut opens your recent Downloads list directly inside the browser?', 'Ctrl + B', 'Ctrl + J', 'Alt + F4', 'Ctrl + U', 'b'),
  (11, 'Web Browsing & Internet', 'easy', 'What are website "Cookies" in everyday browsing?', 'Free gift vouchers', 'Music playlists', 'Tiny text files saved by websites in your browser to remember things like your login status or dark-mode preference', 'Harmful hardware chips', 'c'),
  (11, 'Web Browsing & Internet', 'easy', 'In Google Search, putting quotation marks around an exact phrase like `"Maples Academy Khatauli"` helps you find:', 'Only videos', 'Pages that do NOT mention Maples Academy', 'Only images and no text', 'Pages containing that exact phrase with those words together in that order', 'd'),
  (11, 'Web Browsing & Internet', 'easy', 'What is Google Drive or Microsoft OneDrive an example of?', 'A physical pendrive inside your pocket', 'An offline painting program', 'A computer cooling pad', 'Cloud storage — lets you save files online and open or share them from any phone or computer', 'd'),
  (11, 'Web Browsing & Internet', 'easy', 'When sharing a Google Drive project link with your teacher, why should you check whether access is set to "Restricted" vs "Anyone with the link can View"?', 'View access lets anyone delete your account', 'If left "Restricted", your teacher will see "Access Denied" when clicking your submitted link!', 'Restricted links delete the file', 'Links only work on Sundays', 'b'),
  (11, 'Web Browsing & Internet', 'easy', 'On a noisy browser tab playing unexpected music, what does the tiny speaker icon on that tab let you see or do?', 'Print the tab', 'Record your microphone', 'Spot immediately which tab is playing sound and even mute that tab', 'Bookmark the website', 'c'),
  (11, 'Web Browsing & Internet', 'medium', 'What does an email ending in `.edu.in`, `.ac.in`, or `.gov.in` in India tell you about the website/sender?', 'It belongs to a verified Indian educational institution (`.edu.in`/`.ac.in`) or government body (`.gov.in`)', 'It is a gaming server', 'It only works without internet', 'Anyone can buy it anonymously for ₹10 without verification', 'a'),
  (11, 'Web Browsing & Internet', 'medium', 'If you start writing an email in Gmail and close the tab before clicking Send, where is your unfinished message saved automatically?', 'Drafts', 'Spam', 'Sent', 'Starred', 'a'),
  (11, 'Web Browsing & Internet', 'medium', 'What is a "Browser Extension" (or Add-on)?', 'An extra long charging cable', 'A small optional helper tool added inside your browser (which you should install ONLY from trusted creators)', 'A Wi-Fi booster antenna', 'A second monitor screen', 'b'),
  (11, 'Web Browsing & Internet', 'medium', 'If you want to save an online exam admit card or receipt neatly so you can view it offline anytime without internet, what can you select in the Print (`Ctrl + P`) destination menu?', 'Bluetooth Speaker', 'Delete Page', 'Save as PDF', 'Fax Machine', 'c'),
  (11, 'Web Browsing & Internet', 'medium', 'When a random flashy website suddenly asks "Allow this site to send you Notifications?", what is the smart habit if you do not need alerts from it?', 'Restart your router', 'Enter your phone number', 'Always click Allow on every site', 'Click "Block" — allowing shady sites to send notifications floods your screen with fake virus/ad pop-ups!', 'd'),
  (11, 'Web Browsing & Internet', 'medium', 'When sending an email announcement to 50 parents or students who do not know each other, why is `BCC` better than `CC`?', '`BCC` makes the email arrive faster', '`BCC` allows larger attachments', '`CC` deletes the email after reading', '`BCC` (Blind Carbon Copy) keeps everyone’s email address private from the other recipients', 'd'),
  (11, 'Web Browsing & Internet', 'medium', 'In an email thread sent to 40 club members, what happens if you click "Reply All" instead of "Reply"?', 'It deletes all previous emails', 'Your reply goes to ALL 40 people in the group instead of just the sender!', 'It replies only to yourself', 'It translates your message', 'b'),
  (11, 'Web Browsing & Internet', 'hard', 'Look closely at two URLs: `https://sbi.co.in` vs `https://sbi-login-kyc.freehost.xyz`. In the second URL, which company actually owns the real website domain?', 'Google', 'State Bank of India', '`freehost.xyz` — the `sbi-login-kyc` part at the front is just a fake subdomain trick!', 'Reserve Bank of India', 'c'),
  (11, 'Web Browsing & Internet', 'hard', 'If a webpage looks broken or keeps showing an outdated version even after refreshing, what browser step usually fixes it?', 'Hard Refresh (`Ctrl + F5`) or clearing cached images and files for that site', 'Uninstalling Microsoft Word', 'Lowering speaker volume', 'Replacing the mouse', 'a'),
  (11, 'Web Browsing & Internet', 'hard', 'In Chrome/Edge, why is creating separate "Browser Profiles" helpful when two siblings share one home laptop?', 'Each sibling gets their own separate bookmarks, history, and logged-in school accounts without mixing them up', 'It doubles the laptop hard disk size', 'It creates two physical screens', 'It makes Wi-Fi free', 'a'),
  (11, 'Web Browsing & Internet', 'hard', 'Why shouldn’t you blindly trust a shortened mystery link (like `bit.ly/3xYz99`) sent by an unknown stranger?', 'Short links only work on desktop PCs', 'Shortened links hide the real destination website URL until clicked, so they can disguise phishing or scam sites', 'Short links turn off Bluetooth', 'Short links use 10 GB of data', 'b'),
  (11, 'Basic Networking & Connectivity', 'easy', 'If ONE Wi-Fi printer is connected to the school office Wi-Fi router, how many computers on that same Wi-Fi can print to it?', 'Zero — Wi-Fi printers cannot print', 'All authorized computers/phones on that same Wi-Fi network can share and print to it wirelessly', 'Only phones with no SIM card', 'Only a computer plugged into it with an HDMI cable', 'b'),
  (11, 'Basic Networking & Connectivity', 'easy', 'When you mirror your phone or laptop screen wirelessly onto a classroom Smart TV without any cable, what is that feature called?', 'Zipping', 'Incognito Browsing', 'Screen Casting / Screen Mirroring', 'Disk Formatting', 'c'),
  (11, 'Basic Networking & Connectivity', 'easy', 'Every device connected to a network gets an identifying number address (like a house number for delivering data packets). What is it called?', 'Font Size', 'Roll Number', 'PIN Code', 'IP Address', 'd'),
  (11, 'Basic Networking & Connectivity', 'easy', 'You are using a 1.5 GB/day mobile data pack via Hotspot. Watching 2 hours of video at `4K / 2160p` vs `480p` will do what?', '`4K` uses less data than `480p`', 'Both use zero mobile data', 'Resolution only affects audio volume', '`4K` uses many times more mobile data and can finish your 1.5 GB pack very quickly!', 'd'),
  (11, 'Basic Networking & Connectivity', 'easy', 'On a laptop connected to someone’s mobile Hotspot, turning ON "Metered Connection" (or Data Saver) helps because:', 'It doubles keyboard speed', 'It pauses huge background Windows updates so your friend’s mobile data does not drain suddenly', 'It makes the screen brighter', 'It uninstalls browsers', 'b'),
  (11, 'Basic Networking & Connectivity', 'easy', 'On modern dual-band home Wi-Fi routers, you often see two Wi-Fi names: `Home_2.4G` and `Home_5G`. What is the practical difference?', 'There is no difference at all', '`5G` Wi-Fi requires a 5G SIM card inside the router', '`5 GHz` gives faster speeds nearby in the same room; `2.4 GHz` reaches farther through walls', '`2.4G` works only at 2:40 PM', 'c'),
  (11, 'Basic Networking & Connectivity', 'easy', 'What is "Quick Share / Nearby Share / AirDrop" on modern phones and laptops used for?', 'Sending photos or project files fast between two nearby devices wirelessly without wasting internet data', 'Deleting duplicate contacts', 'Scanning paper books', 'Charging another phone from 10 meters away', 'a'),
  (11, 'Basic Networking & Connectivity', 'medium', 'Why should you avoid logging into banking or sensitive accounts on an open, password-free public Wi-Fi at a railway station or café?', 'Unsecured open Wi-Fi networks make it easier for attackers nearby to snoop on traffic or set up fake twin hotspots', 'Public Wi-Fi drains battery 10x faster', 'Public Wi-Fi breaks your phone camera', 'Public Wi-Fi deletes SIM contacts', 'a'),
  (11, 'Basic Networking & Connectivity', 'medium', 'In online video calls or multiplayer games, what does "High Ping / High Latency" (e.g., 450 ms instead of 25 ms) feel like?', 'Extra crisp sound quality', 'A noticeable delay or lag between clicking/speaking and getting a response back', 'More storage space', 'Higher screen brightness', 'b'),
  (11, 'Basic Networking & Connectivity', 'medium', 'What brings ultrahigh-speed broadband into modern schools and homes using hair-thin strands of glass carrying pulses of light?', 'VGA Monitor Cable', 'Printer Ribbon', 'Fiber-Optic Cable', 'Aux Audio Cable', 'c'),
  (11, 'Basic Networking & Connectivity', 'medium', 'If the home internet suddenly stops working on ALL phones and laptops at once, what safe 1-minute step often resolves a stuck router?', 'Cut the fiber cable', 'Reinstall Windows', 'Factory-reset every phone in the house', 'Power-cycle the router: turn it OFF, wait 15–30 seconds, and turn it back ON', 'd'),
  (11, 'Basic Networking & Connectivity', 'medium', 'What does "NFC" (Near Field Communication) on modern phones and smart cards allow?', 'Long-distance satellite TV reception', 'Printing paper documents', 'Cooling the battery', 'Tap-to-pay or instant pairing when held within a few centimeters of a reader/tag', 'd'),
  (11, 'Basic Networking & Connectivity', 'medium', 'When you type `mapleskhatauli.com` in your browser, which behind-the-scenes internet phonebook translates that friendly name into the server’s numeric IP address?', 'USB (Serial Bus)', 'DNS (Domain Name System)', 'UPS (Power Supply)', 'PDF (Document Format)', 'b'),
  (11, 'Basic Networking & Connectivity', 'medium', 'Your internet speed test shows `100 Mbps` (Megabits per second). Since 8 bits = 1 Byte, roughly how many Megabytes (`MB`) can download in 1 second?', '0.1 MB per second', 'Exactly 800 MB per second', 'Around 12.5 MB per second (`100 ÷ 8`)', '100 GB per second', 'c'),
  (11, 'Basic Networking & Connectivity', 'hard', 'Why is setting up a separate "Guest Wi-Fi" network on a home or school router a smart security practice for visitors?', 'Visitors get internet access while keeping your main school/home computers and shared printers isolated and private', 'Guest Wi-Fi doubles your ISP plan speed', 'Guest Wi-Fi works 5 km away', 'Guest Wi-Fi needs no electricity', 'a'),
  (11, 'Basic Networking & Connectivity', 'hard', 'What is "USB Tethering" between a smartphone and a desktop PC that has no Wi-Fi adapter?', 'Sharing your phone’s internet connection directly to the desktop PC through a normal USB charging/data cable!', 'Tying the phone to the desk with a rope', 'Printing photos directly from SIM card', 'Formatting the phone', 'a'),
  (11, 'Basic Networking & Connectivity', 'hard', 'What is the role of a "Firewall" in Windows or a school router?', 'It prevents physical fire in the computer room', 'It monitors incoming and outgoing network traffic and blocks unauthorized outside connections', 'It deletes old browser bookmarks', 'It heats up the CPU in winter', 'b'),
  (11, 'Basic Networking & Connectivity', 'hard', 'Why should you change the default admin login (`admin / admin`) printed on the bottom sticker of a new home Wi-Fi router?', 'Default passwords use more electricity', 'It voids the monitor warranty', 'Anyone connected nearby who knows common default logins could open router settings and change your Wi-Fi or DNS!', 'Otherwise Wi-Fi turns off after 24 hours', 'c'),
  (11, 'Social Ethics & Cyber Safety', 'easy', 'What does your "Digital Footprint" mean?', 'A fingerprint unlock sensor', 'The size of your laptop in inches', 'The lasting trail of posts, comments, photos, and public activity associated with you on the internet', 'Walking barefoot in the computer lab', 'c'),
  (11, 'Social Ethics & Cyber Safety', 'easy', 'Why is downloading "Cracked / Pirated" paid software or game cheats from shady websites dangerous as well as unethical?', 'Official free alternatives like VLC, GIMP, or LibreOffice do not exist', 'It upgrades your monitor', 'Cracked software runs faster and safer than official apps', 'Besides disrespecting creators’ work, pirated cracks are one of the #1 ways password-stealing malware infects home PCs!', 'd'),
  (11, 'Social Ethics & Cyber Safety', 'easy', 'Before clicking "Save Password" when Chrome asks on a shared school or cyber-café computer, what should you ALWAYS choose?', 'Click "Save" so you never have to type again', 'Write your password on a sticky note on the monitor', 'Share it with the café owner', 'Click "Never" — saving your password on a shared computer lets the next person log straight into your account!', 'd'),
  (11, 'Social Ethics & Cyber Safety', 'easy', 'In a class study WhatsApp/Telegram group, what keeps the group helpful and respectful for everyone?', 'Starting personal arguments in front of 60 people', 'Keeping messages relevant, polite, avoiding late-night spam chains, and respecting classmates’ opinions', 'Sending 80 stickers in a row at midnight', 'Forwarding unverified rumors', 'b'),
  (11, 'Social Ethics & Cyber Safety', 'easy', 'Why do phones and Windows regularly release "Security Updates"?', 'To erase your photos', 'Only to change icon colors', 'To patch newly discovered security holes so hackers and malware cannot exploit them', 'To slow down your internet', 'c'),
  (11, 'Social Ethics & Cyber Safety', 'easy', 'If a classmate accidentally left their Gmail open on a school lab computer, what is the ONLY ethical thing to do?', 'Immediately click "Sign Out" without reading a single email, and politely let them know to be careful next time', 'Send a prank email from their account', 'Change their account password', 'Read their private emails for fun', 'a'),
  (11, 'Social Ethics & Cyber Safety', 'easy', 'Sometimes AI chatbots confidently make up a fake book title, date, or fact that sounds very believable. What should you do before putting AI facts into a school project?', 'Verify important facts, dates, and quotes from a reliable textbook or trusted official website', 'Assume computers can never be wrong', 'Never read what you submit', 'Turn off spell check', 'a'),
  (11, 'Social Ethics & Cyber Safety', 'medium', 'Why is keeping phones on silent and putting screens away at least 30–45 minutes before sleep recommended by doctors?', 'Phones stop working after 10 PM', 'Bright late-night screens and endless notifications disturb deep sleep and leave you tired in class the next morning', 'Batteries charge only when silent', 'Night Wi-Fi costs double', 'b'),
  (11, 'Social Ethics & Cyber Safety', 'medium', 'If you receive an uncomfortable, threatening, or scam message from an unknown account online, what 3 steps protect you best?', 'Click every link they sent', 'Keep it secret and worry alone', 'Do NOT reply or argue — take a screenshot as proof if needed, Block/Report the account, and tell a trusted parent or teacher', 'Send them your phone number to argue back', 'c'),
  (11, 'Social Ethics & Cyber Safety', 'medium', 'What is "Plagiarism" in school projects and digital work?', 'Checking spelling in Word', 'Using open-source software legally', 'Saving a backup copy on a pendrive', 'Copying someone else’s article, code, or artwork and presenting it as your own original work without credit', 'd'),
  (11, 'Social Ethics & Cyber Safety', 'medium', 'When sitting at a computer desk for an hour, what healthy posture avoids neck and back ache?', 'Bend your neck 90 degrees inches from the keyboard', 'Twist sideways on one leg', 'Keep the monitor on the floor', 'Sit upright with feet flat, shoulders relaxed, and top of the screen near eye level rather than hunching low', 'd'),
  (11, 'Social Ethics & Cyber Safety', 'medium', 'What is India’s official national Cyber Crime Helpline number (and portal `cybercrime.gov.in`) in case a family member faces online financial fraud?', '108', '1930', '101', '139', 'b'),
  (11, 'Social Ethics & Cyber Safety', 'medium', 'What is a "Deepfake" video or voice clip that everyone on social media needs to be aware of today?', 'An encrypted ZIP file', 'A high-resolution underwater nature video', 'An AI-manipulated video or cloned voice that makes a real person appear to say or do something they NEVER actually did', 'A backup stored deep inside a folder', 'c'),
  (11, 'Social Ethics & Cyber Safety', 'medium', 'Someone calls your parent in panic using a realistic-sounding voice saying "Send ₹10,000 urgently to this new number, don’t tell anyone!" What is the smart verification habit?', 'Pause, hang up, and call the family member directly on their REAL known phone number to verify before sending a rupee!', 'Share bank OTPs on the call', 'Install a screen-sharing app they suggest', 'Transfer money within 10 seconds in panic', 'a'),
  (11, 'Social Ethics & Cyber Safety', 'hard', 'Why do scammers urgently ask victims to install remote screen-sharing apps (like AnyDesk / TeamViewer / unknown `.apk`s) during fake "KYC / customer care" calls?', 'Because screen-sharing lets the scammer see your live phone screen, including incoming bank OTPs and apps!', 'To clean dust from your phone speaker', 'To double your mobile battery life', 'Banks require AnyDesk for every account', 'a'),
  (11, 'Social Ethics & Cyber Safety', 'hard', 'When designing a club registration form (Data Minimization principle), which information is ethical and sensible to collect?', 'Parents’ bank account numbers and Aadhaar passwords', 'Only what is genuinely needed for the club (Name, Roll No, Class, Section) — never unnecessary private family/financial data!', 'Personal email passwords', 'Home Wi-Fi passwords of every student', 'b'),
  (11, 'Social Ethics & Cyber Safety', 'hard', 'What does a "Creative Commons (CC)" license on an online photo or music track tell students making a video project?', 'Nobody is allowed to view the image', 'You can sell it as your own painting without credit', 'The creator has given clear permission to reuse the work under stated conditions (such as giving proper attribution/credit)', 'The file contains a virus', 'c'),
  (11, 'Social Ethics & Cyber Safety', 'hard', 'What should families do with old dead batteries, broken chargers, and discarded electronics ("E-Waste") instead of burning them or tossing them in open drains?', 'Break screens with a hammer in class', 'Throw batteries into rivers', 'Burn plastic circuit boards in the backyard', 'Hand them over to authorized E-Waste collection/recycling centers so toxic metals don’t pollute soil and water', 'd');
